-- =====================================================================
-- V1__init.sql : 일로 초기 스키마 (ERDCloud '일로' 22개 테이블 기준)
--
-- - PK는 BIGINT IDENTITY (Entity는 @GeneratedValue(strategy = IDENTITY))
-- - 시각은 TIMESTAMPTZ, 영업·점심 시간은 TIME, JSON은 JSONB
-- - 상태값은 VARCHAR + CHECK (Entity는 @Enumerated(EnumType.STRING))
-- - ERD 주석의 UNIQUE·부분 UNIQUE·CHECK·EXCLUDE·updated_at 트리거를 SQL로 구현
-- - 같은 업체·같은 문의 소속은 복합 FK로 보장 (예: 다른 업체 고객을 예약에 연결 금지)
-- - 이동시간·여유시간, 차단 일정(owner_block)과 예약의 충돌은 서버에서 검사
-- =====================================================================

-- EXCLUDE에서 owner_id(=)와 시간 범위(&&)를 같이 쓰기 위해 필요
CREATE EXTENSION IF NOT EXISTS btree_gist;


-- ---------------------------------------------------------------------
-- 운영자
-- ---------------------------------------------------------------------
CREATE TABLE admin (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name       VARCHAR(50) NOT NULL,
    phone      VARCHAR(20) NOT NULL,                  -- 로그인 전화번호
    role       VARCHAR(20) NOT NULL DEFAULT 'STAFF',  -- SUPER(전체 관리) / STAFF(일반 운영) (O06)
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_admin_phone UNIQUE (phone),
    CONSTRAINT ck_admin_role CHECK (role IN ('SUPER', 'STAFF'))
);


-- ---------------------------------------------------------------------
-- 업체(사장님)와 운영 설정
-- ---------------------------------------------------------------------
CREATE TABLE owner (
    id                   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    contact_phone        VARCHAR(20),                        -- 고객에게 보여줄 대표 연락처, 비면 phone 사용 (B11)
    owner_name           VARCHAR(50),                        -- 대표자 이름 (B03)
    business_name        VARCHAR(100) NOT NULL,              -- 상호
    phone                VARCHAR(20)  NOT NULL,              -- 로그인 전화번호
    address              VARCHAR(255),                       -- 기본 출발지 주소
    lat                  NUMERIC(10, 7),
    lng                  NUMERIC(10, 7),
    travel_mode          VARCHAR(20)  NOT NULL DEFAULT 'CAR', -- CAR (초기 고정, TRANSIT 미노출)
    buffer_minutes       INTEGER      NOT NULL DEFAULT 15,   -- 예약 사이 여유시간(분), 이동시간과 별도 (B08)
    lunch_start          TIME,
    lunch_end            TIME,
    max_daily_visits     INTEGER,
    auto_booking_enabled BOOLEAN      NOT NULL DEFAULT false, -- 승인만으로 켜지지 않음, 사장님이 직접 켬
    link_token           VARCHAR(64)  NOT NULL,              -- 업체 고정 접수 링크 토큰
    status               VARCHAR(20)  NOT NULL DEFAULT 'READY', -- READY / ACTIVE / RESTRICTED / WITHDRAWN (APPROVED일 때만 의미)
    intake_paused        BOOLEAN      NOT NULL DEFAULT false, -- 신규 접수 중지 (B09), 기존 대화·예약 접근은 유지
    customer_notice      VARCHAR(500),                       -- 고객 안내 문구 (B05)
    notify_settings      JSONB,                              -- 알림 유형별 수신 여부 (B27)
    created_at           TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at           TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    reviewed_at          TIMESTAMPTZ,                        -- 검토 시각 (승인·거절 공통)
    reviewed_by          BIGINT,                             -- 검토한 운영자, 검토 전이면 null
    service_description  VARCHAR(255),                       -- 고객에게 보여줄 제공 서비스 문구 (B11)
    approval_status      VARCHAR(20)  NOT NULL DEFAULT 'PENDING', -- PENDING / APPROVED / REJECTED (status와 별개)
    rejection_reason     VARCHAR(255),                       -- REJECTED일 때 필수
    CONSTRAINT fk_owner_reviewed_by FOREIGN KEY (reviewed_by) REFERENCES admin (id),
    CONSTRAINT uq_owner_phone UNIQUE (phone),
    CONSTRAINT uq_owner_link_token UNIQUE (link_token),
    CONSTRAINT ck_owner_travel_mode CHECK (travel_mode IN ('CAR', 'TRANSIT')),
    CONSTRAINT ck_owner_status CHECK (status IN ('READY', 'ACTIVE', 'RESTRICTED', 'WITHDRAWN')),
    CONSTRAINT ck_owner_approval_status CHECK (approval_status IN ('PENDING', 'APPROVED', 'REJECTED')),
    CONSTRAINT ck_owner_rejection_reason CHECK (
        approval_status <> 'REJECTED' OR (rejection_reason IS NOT NULL AND btrim(rejection_reason) <> '')),
    CONSTRAINT ck_owner_buffer_minutes CHECK (buffer_minutes >= 0),
    CONSTRAINT ck_owner_max_daily_visits CHECK (max_daily_visits > 0),
    CONSTRAINT ck_owner_lunch CHECK (
        (lunch_start IS NULL AND lunch_end IS NULL)
        OR (lunch_start IS NOT NULL AND lunch_end IS NOT NULL AND lunch_end > lunch_start)),
    CONSTRAINT ck_owner_lat CHECK (lat BETWEEN -90 AND 90),
    CONSTRAINT ck_owner_lng CHECK (lng BETWEEN -180 AND 180)
);

CREATE TABLE owner_business_hour (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    owner_id    BIGINT  NOT NULL,
    day_of_week INTEGER NOT NULL,               -- 1=월 ~ 7=일 (java.time.DayOfWeek와 같음)
    open_time   TIME,
    close_time  TIME,
    is_closed   BOOLEAN NOT NULL DEFAULT false, -- true면 open_time·close_time은 비움
    CONSTRAINT fk_owner_business_hour_owner FOREIGN KEY (owner_id) REFERENCES owner (id),
    CONSTRAINT uq_owner_business_hour_owner_day UNIQUE (owner_id, day_of_week),
    CONSTRAINT ck_owner_business_hour_day CHECK (day_of_week BETWEEN 1 AND 7),
    CONSTRAINT ck_owner_business_hour_times CHECK (
        (is_closed AND open_time IS NULL AND close_time IS NULL)
        OR (NOT is_closed AND open_time IS NOT NULL AND close_time IS NOT NULL AND close_time > open_time))
);

CREATE TABLE owner_service_area (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    owner_id    BIGINT      NOT NULL,
    region_code VARCHAR(10) NOT NULL, -- 시군구 코드 (카카오 주소 API), 고객 주소 코드와 비교
    region_name VARCHAR(50) NOT NULL, -- 화면 표시용 (예: 고양시 덕양구)
    CONSTRAINT fk_owner_service_area_owner FOREIGN KEY (owner_id) REFERENCES owner (id),
    CONSTRAINT uq_owner_service_area_owner_region UNIQUE (owner_id, region_code)
);

CREATE TABLE owner_work_type (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    owner_id         BIGINT      NOT NULL,
    work_category    VARCHAR(20) NOT NULL,              -- INSPECTION / REPAIR / LEAK / REPLACEMENT
    duration_minutes INTEGER     NOT NULL,              -- 소요시간(분), AI가 예측하지 않고 여기서 조회
    is_active        BOOLEAN     NOT NULL DEFAULT true, -- 삭제 대신 false (과거 기록 보존, B05)
    CONSTRAINT fk_owner_work_type_owner FOREIGN KEY (owner_id) REFERENCES owner (id),
    CONSTRAINT uq_owner_work_type_owner_category UNIQUE (owner_id, work_category),
    CONSTRAINT uq_owner_work_type_id_owner UNIQUE (id, owner_id), -- 같은 업체 복합 FK 대상
    CONSTRAINT ck_owner_work_type_category CHECK (work_category IN ('INSPECTION', 'REPAIR', 'LEAK', 'REPLACEMENT')),
    CONSTRAINT ck_owner_work_type_duration CHECK (duration_minutes > 0)
);

CREATE TABLE owner_block (
    id       BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    owner_id BIGINT      NOT NULL,
    start_at TIMESTAMPTZ NOT NULL,
    end_at   TIMESTAMPTZ NOT NULL,
    reason   VARCHAR(100), -- 개인 일정 / 전화 업무 등
    CONSTRAINT fk_owner_block_owner FOREIGN KEY (owner_id) REFERENCES owner (id),
    CONSTRAINT ck_owner_block_time CHECK (end_at > start_at)
);

CREATE INDEX ix_owner_block_owner_start ON owner_block (owner_id, start_at);


-- ---------------------------------------------------------------------
-- 보일러 오류코드 표
-- ---------------------------------------------------------------------
CREATE TABLE error_code (
    id                   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    manufacturer         VARCHAR(50)  NOT NULL,
    code                 VARCHAR(20)  NOT NULL,              -- 예: E01
    meaning              VARCHAR(255) NOT NULL,              -- 예: 점화 불량
    work_category        VARCHAR(20),                        -- owner_work_type.work_category와 같은 값
    parts_hint           VARCHAR(255),                       -- 챙겨갈 부품 가능성
    requires_owner_check BOOLEAN      NOT NULL DEFAULT false, -- 무조건 사장님 확인 대상
    source               VARCHAR(255),                       -- 출처 URL
    CONSTRAINT uq_error_code_manufacturer_code UNIQUE (manufacturer, code),
    CONSTRAINT ck_error_code_work_category CHECK (work_category IN ('INSPECTION', 'REPAIR', 'LEAK', 'REPLACEMENT'))
);


-- ---------------------------------------------------------------------
-- 고객
-- ---------------------------------------------------------------------
CREATE TABLE customer (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    owner_id   BIGINT      NOT NULL, -- 업체별로 고객 분리
    name       VARCHAR(50),
    phone      VARCHAR(20) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_customer_owner FOREIGN KEY (owner_id) REFERENCES owner (id),
    CONSTRAINT uq_customer_owner_phone UNIQUE (owner_id, phone),
    CONSTRAINT uq_customer_id_owner UNIQUE (id, owner_id) -- 같은 업체 복합 FK 대상
);


-- ---------------------------------------------------------------------
-- 문의(상담)
-- ---------------------------------------------------------------------
CREATE TABLE inquiry (
    id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    owner_id          BIGINT       NOT NULL,
    customer_id       BIGINT,                                  -- 초기에는 null 가능
    token_hash        VARCHAR(64)  NOT NULL,                   -- 문의 접근 토큰의 SHA-256 해시 (원문 저장 금지)
    status            VARCHAR(20)  NOT NULL DEFAULT 'COLLECTING', -- COLLECTING / SCHEDULING / OWNER_CHECK / BOOKED / UNSERVICEABLE / CLOSED
    channel           VARCHAR(20)  NOT NULL DEFAULT 'WEB',     -- WEB / KAKAO(추후 확장)
    symptom           VARCHAR(255),
    address           VARCHAR(255),
    lat               NUMERIC(10, 7),
    lng               NUMERIC(10, 7),
    access_note       VARCHAR(255),                            -- 주차·출입 등 추가 안내 (C06)
    manufacturer      VARCHAR(50),                             -- LLM 추출 현재값 (출처·확인 여부는 inquiry_field)
    model             VARCHAR(100),
    boiler_type       VARCHAR(50),
    error_code        VARCHAR(20),                             -- 오류코드 원문
    error_code_id     BIGINT,                                  -- 오류코드 표 조회 성공 시
    work_type_id      BIGINT,                                  -- 분류된 작업 유형
    handler_mode      VARCHAR(10)  NOT NULL DEFAULT 'AI',      -- AI / OWNER, 동시 답변 방지 (B15)
    version           INTEGER      NOT NULL DEFAULT 0,         -- 낙관적 잠금
    safety_flag       BOOLEAN      NOT NULL DEFAULT false,     -- true면 자동 예약·AI 재개 차단 (C09·B16)
    ai_summary        TEXT,                                    -- AI 요약 (B13), 생성 실패 시 null
    expires_at        TIMESTAMPTZ,                             -- 토큰 만료
    created_at        TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at        TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted_at        TIMESTAMPTZ,                             -- 값이 있으면 목록·상세 조회 차단 (B12·O09)
    address_detail    VARCHAR(255),                            -- 상세 주소 (동·호수), 지도 API엔 address만 사용 (C04)
    phone_verified_at TIMESTAMPTZ,                             -- 고객 전화번호 인증 시각, null이면 예약 확정 불가
    CONSTRAINT fk_inquiry_owner FOREIGN KEY (owner_id) REFERENCES owner (id),
    CONSTRAINT fk_inquiry_customer FOREIGN KEY (customer_id) REFERENCES customer (id),
    CONSTRAINT fk_inquiry_error_code FOREIGN KEY (error_code_id) REFERENCES error_code (id),
    CONSTRAINT fk_inquiry_work_type FOREIGN KEY (work_type_id) REFERENCES owner_work_type (id),
    CONSTRAINT fk_inquiry_customer_same_owner FOREIGN KEY (customer_id, owner_id) REFERENCES customer (id, owner_id),
    CONSTRAINT fk_inquiry_work_type_same_owner FOREIGN KEY (work_type_id, owner_id) REFERENCES owner_work_type (id, owner_id),
    CONSTRAINT uq_inquiry_token_hash UNIQUE (token_hash),
    CONSTRAINT uq_inquiry_id_owner UNIQUE (id, owner_id), -- 같은 업체 복합 FK 대상
    CONSTRAINT ck_inquiry_status CHECK (status IN ('COLLECTING', 'SCHEDULING', 'OWNER_CHECK', 'BOOKED', 'UNSERVICEABLE', 'CLOSED')),
    CONSTRAINT ck_inquiry_channel CHECK (channel IN ('WEB', 'KAKAO')),
    CONSTRAINT ck_inquiry_handler_mode CHECK (handler_mode IN ('AI', 'OWNER')),
    CONSTRAINT ck_inquiry_version CHECK (version >= 0),
    CONSTRAINT ck_inquiry_lat CHECK (lat BETWEEN -90 AND 90),
    CONSTRAINT ck_inquiry_lng CHECK (lng BETWEEN -180 AND 180)
);

CREATE INDEX ix_inquiry_owner_status ON inquiry (owner_id, status, created_at) WHERE deleted_at IS NULL;
CREATE INDEX ix_inquiry_customer ON inquiry (customer_id);

CREATE TABLE consent (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    inquiry_id    BIGINT      NOT NULL, -- 대화·사진 수집 전에 먼저 기록 (C01·C06)
    consent_type  VARCHAR(30) NOT NULL, -- PRIVACY_REQUIRED / PHOTO
    terms_version VARCHAR(20) NOT NULL,
    agreed_at     TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_consent_inquiry FOREIGN KEY (inquiry_id) REFERENCES inquiry (id),
    CONSTRAINT ck_consent_type CHECK (consent_type IN ('PRIVACY_REQUIRED', 'PHOTO'))
);

CREATE INDEX ix_consent_inquiry ON consent (inquiry_id);

CREATE TABLE message (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    inquiry_id      BIGINT      NOT NULL,
    sender          VARCHAR(20) NOT NULL,                   -- CUSTOMER / AI / OWNER
    ai_decision_id  BIGINT,                                 -- 이 답변을 만든 AI 판단 (O10), FK는 ai_decision 생성 뒤 추가
    content         TEXT,
    delivery_status VARCHAR(20) NOT NULL DEFAULT 'PENDING', -- PENDING / SENT / FAILED, 실패를 성공처럼 표시 금지 (C11·B15)
    client_msg_id   VARCHAR(64),                            -- 클라이언트 생성 ID, 재전송 중복 방지 (C04)
    created_at      TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_message_inquiry FOREIGN KEY (inquiry_id) REFERENCES inquiry (id),
    CONSTRAINT uq_message_inquiry_client_msg UNIQUE (inquiry_id, client_msg_id),
    CONSTRAINT uq_message_id_inquiry UNIQUE (id, inquiry_id), -- 같은 문의 복합 FK 대상
    CONSTRAINT ck_message_sender CHECK (sender IN ('CUSTOMER', 'AI', 'OWNER')),
    CONSTRAINT ck_message_delivery_status CHECK (delivery_status IN ('PENDING', 'SENT', 'FAILED')),
    CONSTRAINT ck_message_ai_decision CHECK (ai_decision_id IS NULL OR sender = 'AI')
);

CREATE INDEX ix_message_inquiry_created ON message (inquiry_id, created_at, id);

CREATE TABLE photo (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    inquiry_id      BIGINT       NOT NULL,
    message_id      BIGINT,
    s3_key_original VARCHAR(255) NOT NULL,
    s3_key_resized  VARCHAR(255),                             -- 1024px 리사이즈본, LLM에는 이것만 전송
    mime_type       VARCHAR(50)  NOT NULL,                    -- 미지원 형식 구분 안내 (C05)
    size_bytes      BIGINT       NOT NULL,                    -- 용량 초과 구분 안내 (C05)
    upload_status   VARCHAR(20)  NOT NULL DEFAULT 'UPLOADING', -- UPLOADING / DONE / FAILED, 실패한 사진만 재전송 (C05)
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_photo_inquiry FOREIGN KEY (inquiry_id) REFERENCES inquiry (id),
    CONSTRAINT fk_photo_message FOREIGN KEY (message_id) REFERENCES message (id),
    CONSTRAINT fk_photo_message_same_inquiry FOREIGN KEY (message_id, inquiry_id) REFERENCES message (id, inquiry_id),
    CONSTRAINT uq_photo_id_inquiry UNIQUE (id, inquiry_id), -- 같은 문의 복합 FK 대상
    CONSTRAINT ck_photo_upload_status CHECK (upload_status IN ('UPLOADING', 'DONE', 'FAILED')),
    CONSTRAINT ck_photo_size CHECK (size_bytes > 0)
);

CREATE INDEX ix_photo_inquiry ON photo (inquiry_id);

CREATE TABLE ai_decision (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    inquiry_id     BIGINT      NOT NULL,
    message_id     BIGINT,                -- 이 판단을 만든 고객 메시지
    stage          VARCHAR(20) NOT NULL,  -- EXTRACT / DECIDE / SUMMARY
    model_name     VARCHAR(100),          -- LLM 모델 ID, decided_by가 RULE이면 null
    prompt_version VARCHAR(20),
    input_snapshot JSONB,                 -- LLM에 보낸 대화·수집 상태
    output_raw     JSONB,                 -- LLM 원본 응답
    intent         VARCHAR(20),           -- ANSWER / CORRECTION / SIDE_QUESTION / TIME_SELECT / END / COMPLAINT
    confidence     NUMERIC(3, 2),         -- 0.00 ~ 1.00
    action         VARCHAR(30) NOT NULL,  -- ASK_MORE_INFO / REQUEST_IMAGE / ANSWER_SIDE_QUESTION / CHECK_SCHEDULE / COMPLETE / ESCALATE_TO_OWNER / UNSERVICEABLE
    rule_reason    VARCHAR(30),           -- MISSING_FIELD / OUT_OF_AREA / SAFETY / LOW_CONFIDENCE / DONE
    decided_by     VARCHAR(30) NOT NULL,  -- RULE / EXTERNAL_API / SELF_MODEL / JEV
    latency_ms     INTEGER,
    input_tokens   INTEGER,
    output_tokens  INTEGER,
    status         VARCHAR(20) NOT NULL,  -- SUCCESS / FAILED / TIMEOUT, 실패 시 사장님 확인 전환·재처리 대상 (C09·O08)
    error_message  VARCHAR(500),          -- 인증정보·불필요한 고객 원문 제외 (O07)
    created_at     TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    rule_version   VARCHAR(50),           -- 적용한 업무 규칙(YAML) 버전·커밋, 원본은 GitHub
    CONSTRAINT fk_ai_decision_inquiry FOREIGN KEY (inquiry_id) REFERENCES inquiry (id),
    CONSTRAINT fk_ai_decision_message FOREIGN KEY (message_id) REFERENCES message (id),
    CONSTRAINT fk_ai_decision_message_same_inquiry FOREIGN KEY (message_id, inquiry_id) REFERENCES message (id, inquiry_id),
    CONSTRAINT uq_ai_decision_id_inquiry UNIQUE (id, inquiry_id), -- 같은 문의 복합 FK 대상
    CONSTRAINT ck_ai_decision_stage CHECK (stage IN ('EXTRACT', 'DECIDE', 'SUMMARY')),
    CONSTRAINT ck_ai_decision_intent CHECK (intent IN ('ANSWER', 'CORRECTION', 'SIDE_QUESTION', 'TIME_SELECT', 'END', 'COMPLAINT')),
    CONSTRAINT ck_ai_decision_action CHECK (action IN (
        'ASK_MORE_INFO', 'REQUEST_IMAGE', 'ANSWER_SIDE_QUESTION', 'CHECK_SCHEDULE', 'COMPLETE', 'ESCALATE_TO_OWNER', 'UNSERVICEABLE')),
    CONSTRAINT ck_ai_decision_rule_reason CHECK (rule_reason IN ('MISSING_FIELD', 'OUT_OF_AREA', 'SAFETY', 'LOW_CONFIDENCE', 'DONE')),
    CONSTRAINT ck_ai_decision_decided_by CHECK (decided_by IN ('RULE', 'EXTERNAL_API', 'SELF_MODEL', 'JEV')),
    CONSTRAINT ck_ai_decision_status CHECK (status IN ('SUCCESS', 'FAILED', 'TIMEOUT')),
    CONSTRAINT ck_ai_decision_rule_model CHECK (decided_by <> 'RULE' OR model_name IS NULL),
    CONSTRAINT ck_ai_decision_confidence CHECK (confidence BETWEEN 0 AND 1),
    CONSTRAINT ck_ai_decision_latency CHECK (latency_ms >= 0),
    CONSTRAINT ck_ai_decision_input_tokens CHECK (input_tokens >= 0),
    CONSTRAINT ck_ai_decision_output_tokens CHECK (output_tokens >= 0)
);

CREATE INDEX ix_ai_decision_inquiry_created ON ai_decision (inquiry_id, created_at);

-- message ↔ ai_decision은 서로를 가리키므로 두 테이블을 만든 뒤 FK 추가
ALTER TABLE message
    ADD CONSTRAINT fk_message_ai_decision FOREIGN KEY (ai_decision_id) REFERENCES ai_decision (id),
    ADD CONSTRAINT fk_message_ai_decision_same_inquiry FOREIGN KEY (ai_decision_id, inquiry_id) REFERENCES ai_decision (id, inquiry_id);

CREATE TABLE inquiry_field (
    id                 BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    inquiry_id         BIGINT      NOT NULL,
    field_key          VARCHAR(30) NOT NULL,              -- manufacturer / model / boiler_type / error_code / symptom 등
    field_value        VARCHAR(255),                      -- 미확인이면 null
    source             VARCHAR(20) NOT NULL,              -- CUSTOMER / PHOTO / OWNER
    status             VARCHAR(20) NOT NULL,              -- CONFIRMED / UNCONFIRMED, 추정값을 사진 확인으로 표시 금지
    photo_id           BIGINT,                            -- 근거 사진 (source가 PHOTO일 때)
    ai_decision_id     BIGINT,                            -- 이 값을 만든 AI 호출 (O10)
    unconfirmed_reason VARCHAR(100),                      -- 사장님 확인이 필요한 이유 (C05)
    is_current         BOOLEAN     NOT NULL DEFAULT true, -- 수정 시 이전 행은 false로 남겨 이력 보존 (B14)
    created_at         TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_inquiry_field_inquiry FOREIGN KEY (inquiry_id) REFERENCES inquiry (id),
    CONSTRAINT fk_inquiry_field_photo FOREIGN KEY (photo_id) REFERENCES photo (id),
    CONSTRAINT fk_inquiry_field_ai_decision FOREIGN KEY (ai_decision_id) REFERENCES ai_decision (id),
    CONSTRAINT fk_inquiry_field_photo_same_inquiry FOREIGN KEY (photo_id, inquiry_id) REFERENCES photo (id, inquiry_id),
    CONSTRAINT fk_inquiry_field_ai_decision_same_inquiry FOREIGN KEY (ai_decision_id, inquiry_id) REFERENCES ai_decision (id, inquiry_id),
    CONSTRAINT ck_inquiry_field_source CHECK (source IN ('CUSTOMER', 'PHOTO', 'OWNER')),
    CONSTRAINT ck_inquiry_field_status CHECK (status IN ('CONFIRMED', 'UNCONFIRMED')),
    CONSTRAINT ck_inquiry_field_photo_evidence CHECK (source <> 'PHOTO' OR photo_id IS NOT NULL)
);

-- 항목별 현재값은 문의당 1개
CREATE UNIQUE INDEX uq_inquiry_field_current ON inquiry_field (inquiry_id, field_key) WHERE is_current;
CREATE INDEX ix_inquiry_field_inquiry_created ON inquiry_field (inquiry_id, created_at);

CREATE TABLE handoff_request (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    inquiry_id   BIGINT      NOT NULL,
    request_type VARCHAR(20) NOT NULL,                   -- DIRECT_CHAT(직접 상담, C10) / CALLBACK(전화 회신, C18)
    name         VARCHAR(50),                            -- CALLBACK일 때 회신받을 이름
    phone        VARCHAR(20),                            -- CALLBACK일 때 회신받을 휴대전화
    status       VARCHAR(20) NOT NULL DEFAULT 'WAITING', -- WAITING / IN_PROGRESS / DONE
    created_at   TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    resolved_at  TIMESTAMPTZ,
    CONSTRAINT fk_handoff_request_inquiry FOREIGN KEY (inquiry_id) REFERENCES inquiry (id),
    CONSTRAINT ck_handoff_request_type CHECK (request_type IN ('DIRECT_CHAT', 'CALLBACK')),
    CONSTRAINT ck_handoff_request_status CHECK (status IN ('WAITING', 'IN_PROGRESS', 'DONE')),
    CONSTRAINT ck_handoff_request_callback_phone CHECK (
        request_type <> 'CALLBACK' OR (phone IS NOT NULL AND btrim(phone) <> ''))
);

-- 진행 중 요청은 문의당 1건 (대기 중 전화 회신을 고르면 같은 요청을 CALLBACK으로 변경)
CREATE UNIQUE INDEX uq_handoff_request_active ON handoff_request (inquiry_id) WHERE status IN ('WAITING', 'IN_PROGRESS');


-- ---------------------------------------------------------------------
-- 예약
-- ---------------------------------------------------------------------
CREATE TABLE reservation (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    inquiry_id          BIGINT,                                  -- 수동 예약이면 null
    owner_id            BIGINT      NOT NULL,
    customer_id         BIGINT,
    start_at            TIMESTAMPTZ NOT NULL,
    end_at              TIMESTAMPTZ NOT NULL,
    address             VARCHAR(255),
    lat                 NUMERIC(10, 7),
    lng                 NUMERIC(10, 7),
    status              VARCHAR(20) NOT NULL DEFAULT 'REQUESTED', -- REQUESTED / CONFIRMED / CANCELED / COMPLETED (변경 진행 상태는 reservation_change)
    work_type_id        BIGINT,
    travel_time_minutes INTEGER,                                 -- 계산에 쓴 이동시간(분), 사후 검증용
    work_minutes        INTEGER,                                 -- 계산에 쓴 작업시간(분), 설정이 바뀌어도 당시 값 보존 (B28)
    buffer_minutes      INTEGER,                                 -- 계산에 쓴 여유시간(분) (B08·B28)
    is_manual           BOOLEAN     NOT NULL DEFAULT false,      -- 사장님 직접 등록
    idempotency_key     VARCHAR(64),                             -- 예약 확정 요청 키, 반복 요청으로 중복 예약 방지 (C13)
    version             INTEGER     NOT NULL DEFAULT 0,          -- 낙관적 잠금, 변경 수락과 취소 동시 처리 방지 (B19·B21)
    created_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_reservation_inquiry FOREIGN KEY (inquiry_id) REFERENCES inquiry (id),
    CONSTRAINT fk_reservation_owner FOREIGN KEY (owner_id) REFERENCES owner (id),
    CONSTRAINT fk_reservation_customer FOREIGN KEY (customer_id) REFERENCES customer (id),
    CONSTRAINT fk_reservation_work_type FOREIGN KEY (work_type_id) REFERENCES owner_work_type (id),
    CONSTRAINT fk_reservation_inquiry_same_owner FOREIGN KEY (inquiry_id, owner_id) REFERENCES inquiry (id, owner_id),
    CONSTRAINT fk_reservation_customer_same_owner FOREIGN KEY (customer_id, owner_id) REFERENCES customer (id, owner_id),
    CONSTRAINT fk_reservation_work_type_same_owner FOREIGN KEY (work_type_id, owner_id) REFERENCES owner_work_type (id, owner_id),
    CONSTRAINT uq_reservation_idempotency_key UNIQUE (idempotency_key),
    CONSTRAINT ck_reservation_status CHECK (status IN ('REQUESTED', 'CONFIRMED', 'CANCELED', 'COMPLETED')),
    CONSTRAINT ck_reservation_time CHECK (end_at > start_at),
    CONSTRAINT ck_reservation_travel_time CHECK (travel_time_minutes >= 0),
    CONSTRAINT ck_reservation_work_minutes CHECK (work_minutes > 0),
    CONSTRAINT ck_reservation_buffer_minutes CHECK (buffer_minutes >= 0),
    CONSTRAINT ck_reservation_version CHECK (version >= 0),
    CONSTRAINT ck_reservation_lat CHECK (lat BETWEEN -90 AND 90),
    CONSTRAINT ck_reservation_lng CHECK (lng BETWEEN -180 AND 180),
    -- 같은 업체의 CONFIRMED 예약끼리 시간 겹침 금지. [시작, 끝) 구간이라 10~11시와 11~12시는 허용
    CONSTRAINT ex_reservation_confirmed_overlap EXCLUDE USING gist (
        owner_id WITH =,
        tstzrange(start_at, end_at, '[)') WITH &&
    ) WHERE (status = 'CONFIRMED')
);

-- 문의당 활성 예약 1건 (CANCELED만 풀림, COMPLETED도 1건으로 셈) (C13)
CREATE UNIQUE INDEX uq_reservation_active_inquiry ON reservation (inquiry_id) WHERE status <> 'CANCELED';
CREATE INDEX ix_reservation_owner_start ON reservation (owner_id, start_at);
CREATE INDEX ix_reservation_customer ON reservation (customer_id);

CREATE TABLE reservation_change (
    id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    reservation_id    BIGINT      NOT NULL,
    change_type       VARCHAR(20) NOT NULL,                     -- CHANGE / CANCEL
    requested_by      VARCHAR(20) NOT NULL,                     -- CUSTOMER / OWNER
    request_note      VARCHAR(255),                             -- 고객 요청 내용 (희망 날짜·시간대 등)
    prev_start_at     TIMESTAMPTZ NOT NULL,                     -- 요청 시점의 기존 시각, 반영 후에도 보존 (C17)
    prev_end_at       TIMESTAMPTZ NOT NULL,
    prev_address      VARCHAR(255),                             -- 요청 시점의 기존 주소
    proposed_start_at TIMESTAMPTZ,                              -- 사장님이 제안한 시각
    proposed_end_at   TIMESTAMPTZ,
    proposed_address  VARCHAR(255),                             -- 주소 변경 요청일 때 (C08·B14·B23)
    proposed_lat      NUMERIC(10, 7),
    proposed_lng      NUMERIC(10, 7),
    status            VARCHAR(20) NOT NULL DEFAULT 'REQUESTED', -- REQUESTED / PROPOSED / ACCEPTED / REJECTED / APPLIED / FAILED, 반영 전까지 기존 예약 유지
    created_at        TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    resolved_at       TIMESTAMPTZ,
    base_version      INTEGER     NOT NULL,                     -- 요청 당시 reservation.version, 다르면 덮어쓰지 않고 재조회
    CONSTRAINT fk_reservation_change_reservation FOREIGN KEY (reservation_id) REFERENCES reservation (id),
    CONSTRAINT ck_reservation_change_type CHECK (change_type IN ('CHANGE', 'CANCEL')),
    CONSTRAINT ck_reservation_change_requested_by CHECK (requested_by IN ('CUSTOMER', 'OWNER')),
    CONSTRAINT ck_reservation_change_status CHECK (status IN ('REQUESTED', 'PROPOSED', 'ACCEPTED', 'REJECTED', 'APPLIED', 'FAILED')),
    CONSTRAINT ck_reservation_change_prev_time CHECK (prev_end_at > prev_start_at),
    CONSTRAINT ck_reservation_change_proposed_time CHECK (
        (proposed_start_at IS NULL AND proposed_end_at IS NULL)
        OR (proposed_start_at IS NOT NULL AND proposed_end_at IS NOT NULL AND proposed_end_at > proposed_start_at)),
    CONSTRAINT ck_reservation_change_base_version CHECK (base_version >= 0),
    CONSTRAINT ck_reservation_change_lat CHECK (proposed_lat BETWEEN -90 AND 90),
    CONSTRAINT ck_reservation_change_lng CHECK (proposed_lng BETWEEN -180 AND 180)
);

-- 진행 중 변경 요청은 예약당 1건
CREATE UNIQUE INDEX uq_reservation_change_active ON reservation_change (reservation_id) WHERE status IN ('REQUESTED', 'PROPOSED', 'ACCEPTED');
CREATE INDEX ix_reservation_change_reservation_created ON reservation_change (reservation_id, created_at);

CREATE TABLE reservation_history (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    reservation_id BIGINT      NOT NULL,
    from_status    VARCHAR(20),          -- 처음 만들 때는 null
    to_status      VARCHAR(20) NOT NULL,
    changed_by     VARCHAR(20) NOT NULL, -- CUSTOMER / OWNER / SYSTEM
    reason         VARCHAR(255),         -- 완료 정정(B25)·업체 사유 취소(B20) 시 기록
    created_at     TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_reservation_history_reservation FOREIGN KEY (reservation_id) REFERENCES reservation (id),
    CONSTRAINT ck_reservation_history_from_status CHECK (from_status IN ('REQUESTED', 'CONFIRMED', 'CANCELED', 'COMPLETED')),
    CONSTRAINT ck_reservation_history_to_status CHECK (to_status IN ('REQUESTED', 'CONFIRMED', 'CANCELED', 'COMPLETED')),
    CONSTRAINT ck_reservation_history_changed_by CHECK (changed_by IN ('CUSTOMER', 'OWNER', 'SYSTEM'))
);

CREATE INDEX ix_reservation_history_reservation_created ON reservation_history (reservation_id, created_at);

CREATE TABLE work_note (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    reservation_id BIGINT      NOT NULL,
    content        TEXT        NOT NULL, -- 사장님 전용 (B24), 고객 화면·알림·요약에 노출 금지
    created_at     TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at     TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_work_note_reservation FOREIGN KEY (reservation_id) REFERENCES reservation (id)
);

CREATE INDEX ix_work_note_reservation ON work_note (reservation_id);


-- ---------------------------------------------------------------------
-- 알림
-- ---------------------------------------------------------------------
CREATE TABLE notification (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    owner_id      BIGINT       NOT NULL,
    recipient     VARCHAR(20)  NOT NULL,                   -- OWNER / CUSTOMER
    event_type    VARCHAR(30)  NOT NULL,                   -- NEW_RESERVATION / NEEDS_CHECK / CHANGE / CANCEL / RESULT
    ref_type      VARCHAR(20)  NOT NULL,                   -- INQUIRY / RESERVATION
    ref_id        BIGINT       NOT NULL,                   -- 대상 문의 또는 예약 ID (ref_type으로 구분, FK 없음)
    channel       VARCHAR(20)  NOT NULL,                   -- IN_APP / WEB_PUSH / SMS
    dedupe_key    VARCHAR(100) NOT NULL,                   -- 같은 이벤트 중복 알림 방지 (B26·C17)
    send_status   VARCHAR(20)  NOT NULL DEFAULT 'PENDING', -- PENDING / SENT / FAILED, 실패 시 재시도 대상
    attempt_count INTEGER      NOT NULL DEFAULT 0,
    read_at       TIMESTAMPTZ,                             -- 외부 발송 실패와 무관하게 미확인 업무 유지
    created_at    TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_notification_owner FOREIGN KEY (owner_id) REFERENCES owner (id),
    CONSTRAINT uq_notification_dedupe_key UNIQUE (dedupe_key),
    CONSTRAINT ck_notification_recipient CHECK (recipient IN ('OWNER', 'CUSTOMER')),
    CONSTRAINT ck_notification_event_type CHECK (event_type IN ('NEW_RESERVATION', 'NEEDS_CHECK', 'CHANGE', 'CANCEL', 'RESULT')),
    CONSTRAINT ck_notification_ref_type CHECK (ref_type IN ('INQUIRY', 'RESERVATION')),
    CONSTRAINT ck_notification_channel CHECK (channel IN ('IN_APP', 'WEB_PUSH', 'SMS')),
    CONSTRAINT ck_notification_send_status CHECK (send_status IN ('PENDING', 'SENT', 'FAILED')),
    CONSTRAINT ck_notification_attempt_count CHECK (attempt_count >= 0)
);

CREATE INDEX ix_notification_owner_created ON notification (owner_id, created_at);
CREATE INDEX ix_notification_retry ON notification (send_status, created_at) WHERE send_status IN ('PENDING', 'FAILED');

CREATE TABLE push_subscription (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    owner_id   BIGINT       NOT NULL,
    endpoint   VARCHAR(500) NOT NULL, -- Web Push endpoint
    p256dh     VARCHAR(255) NOT NULL, -- 구독 공개키
    auth       VARCHAR(255) NOT NULL, -- 구독 인증 secret
    user_agent VARCHAR(255),
    created_at TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_push_subscription_owner FOREIGN KEY (owner_id) REFERENCES owner (id),
    CONSTRAINT uq_push_subscription_endpoint UNIQUE (endpoint)
);

CREATE INDEX ix_push_subscription_owner ON push_subscription (owner_id);


-- ---------------------------------------------------------------------
-- 휴대전화 인증
-- ---------------------------------------------------------------------
CREATE TABLE phone_verification (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    phone         VARCHAR(20)  NOT NULL,
    purpose       VARCHAR(20)  NOT NULL,           -- 목적별로 권한 분리, 고객 인증으로 사장님 세션 발급 금지
    code_hash     VARCHAR(255) NOT NULL,           -- 6자리 인증번호 해시 (원문 저장 금지)
    attempt_count INTEGER      NOT NULL DEFAULT 0, -- 입력 시도 횟수
    send_status   VARCHAR(20)  NOT NULL,           -- SENT / FAILED
    expires_at    TIMESTAMPTZ  NOT NULL,
    verified_at   TIMESTAMPTZ,
    created_at    TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP, -- 재발송 횟수 제한 기준
    CONSTRAINT ck_phone_verification_purpose CHECK (purpose IN (
        'OWNER_SIGNUP', 'OWNER_LOGIN', 'ADMIN_LOGIN', 'CUSTOMER_VERIFY', 'INQUIRY_ACCESS', 'RESERVATION_LOOKUP')),
    CONSTRAINT ck_phone_verification_send_status CHECK (send_status IN ('SENT', 'FAILED')),
    CONSTRAINT ck_phone_verification_attempt_count CHECK (attempt_count >= 0),
    CONSTRAINT ck_phone_verification_expiry CHECK (expires_at > created_at)
);

CREATE INDEX ix_phone_verification_phone_purpose ON phone_verification (phone, purpose, created_at);


-- ---------------------------------------------------------------------
-- updated_at 자동 갱신 (UPDATE 때마다 현재 시각으로)
-- ---------------------------------------------------------------------
CREATE FUNCTION set_updated_at() RETURNS trigger
    LANGUAGE plpgsql AS
$$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_owner_updated_at BEFORE UPDATE ON owner
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_customer_updated_at BEFORE UPDATE ON customer
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_inquiry_updated_at BEFORE UPDATE ON inquiry
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_reservation_updated_at BEFORE UPDATE ON reservation
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_work_note_updated_at BEFORE UPDATE ON work_note
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();
